1	export type Cell = [number, number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const includesCell = (cells: Cell[], cell: Cell): boolean =>
7	  cells.some((candidate) => isSameCell(candidate, cell));
8	
9	const isNeighborOf = (cell: Cell, candidate: Cell): boolean => {
10	  const [x, y] = cell;
11	  const [candidateX, candidateY] = candidate;
12	
13	  return (
14	    Math.abs(candidateX - x) <= 1 &&
15	    Math.abs(candidateY - y) <= 1 &&
16	    !isSameCell(cell, candidate)
17	  );
18	};
19	
20	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
21	  liveCells.filter((candidate) => isNeighborOf(cell, candidate)).length;
22	
23	const survives = (liveNeighbors: number): boolean =>
24	  liveNeighbors === 2 || liveNeighbors === 3;
25	
26	const isReproducing = (liveNeighbors: number): boolean => liveNeighbors === 3;
27	
28	const neighborsOf = ([x, y]: Cell): Cell[] =>
29	  [-1, 0, 1].flatMap((dx) =>
30	    [-1, 0, 1]
31	      .filter((dy) => !(dx === 0 && dy === 0))
32	      .map((dy): Cell => [x + dx, y + dy]),
33	  );
34	
35	export function nextGeneration(liveCells: Cell[]): Cell[] {
36	  const survivors = liveCells.filter((cell) =>
37	    survives(countLiveNeighbors(cell, liveCells)),
38	  );
39	
40	  const births = liveCells
41	    .flatMap(neighborsOf)
42	    .filter(
43	      (candidate) =>
44	        !includesCell(liveCells, candidate) &&
45	        isReproducing(countLiveNeighbors(candidate, liveCells)),
46	    )
47	    .reduce<Cell[]>(
48	      (unique, candidate) =>
49	        includesCell(unique, candidate) ? unique : [...unique, candidate],
50	      [],
51	    );
52	
53	  return [...survivors, ...births];
54	}
